<script setup lang="ts">
import { computed, reactive, ref } from "vue"; import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import DataTable from "@/components/zs/DataTable.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue"; import {useCrmData} from "@/composables/useCrmData"; import {useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("CRM Tasks","Manage sales follow-ups and customer actions.");const data=useCrmData(),open=ref(false);const rows=computed(()=>data.tasks.data.value??[]);const columns=[{key:"title",header:"Task"},{key:"related",header:"Related to"},{key:"owner",header:"Owner"},{key:"dueAt",header:"Due"},{key:"priority",header:"Priority"},{key:"status",header:"Status"},{key:"actions",header:"",align:"right" as const}];const form=reactive({subject:"",description:"",due_at:"",priority:"MEDIUM",owner_id:""});const createMutation=useMutation(()=>crmRepository.createActivity(data.activeCompanyId.value,{type:"TASK",subject:form.subject,description:form.description,due_at:form.due_at||null,priority:form.priority,owner_id:form.owner_id?Number(form.owner_id):null,status:"PENDING"}));const completeMutation=useMutation((id:string)=>crmRepository.transitionActivity(data.activeCompanyId.value,id,"COMPLETED"));async function create(){const saved=await createMutation.run();if(!saved)return;open.value=false;await data.activities.refresh();showToast("Task created",saved.subject,"success");}async function complete(id:string){const saved=await completeMutation.run(id);if(!saved)return;await data.activities.refresh();showToast("Task completed",saved.subject,"success");}
</script>
<template><AppShell><PageHeader title="Tasks" :description="`${rows.filter((item)=>item.status==='PENDING').length} open actions`"><template #actions><ZButton @click="open=true">New task</ZButton></template></PageHeader><Panel><DataTable :columns="columns" :rows="rows" :min-width="900"><template #title="{row}"><span class="font-medium text-content">{{row.title}}</span></template><template #related="{row}">{{row.related?.name||'General'}}</template><template #priority="{row}"><StatusBadge :status="row.priority"/></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" :disabled="row.status!=='PENDING'||completeMutation.saving.value" @click="complete(row.id)">Complete</ZButton></template></DataTable></Panel><SidePanel :open="open" title="New task" @close="open=false"><form class="grid gap-4" @submit.prevent="create"><Field v-model="form.subject" label="Task" required/><Field v-model="form.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Owner</span><select v-model="form.owner_id" class="field mt-1.5"><option value="">Unassigned</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></label><label><span class="label-caps">Priority</span><select v-model="form.priority" class="field mt-1.5"><option>LOW</option><option>MEDIUM</option><option>HIGH</option></select></label><label><span class="label-caps">Description</span><textarea v-model="form.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage :message="createMutation.error.value?.message"/><ZButton type="submit" :disabled="createMutation.saving.value">Create task</ZButton></form></SidePanel></AppShell></template>
